//! The trainer against PyTorch (float32, CPU): loss, the gradient of every parameter and five AdamW steps on a tiny model (tests/golden/train_tiny, generated by tools/gen_train_goldens.py).
//! The GPU path uses fp16 operands and fp16 activations, so gradients agree to about 1e-2 relative, not to float32 precision: the criteria are relative error and cosine similarity per tensor.

use forge_core::Json;
use forge_cuda::Device;
use forge_train::{TrainConfig, Trainer};
use std::collections::HashMap;
use std::path::PathBuf;

fn dir(variant: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/golden/train_tiny")
        .join(variant)
}

fn read_f32(p: PathBuf) -> Vec<f32> {
    std::fs::read(p)
        .unwrap()
        .chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect()
}

fn stats(a: &[f32], b: &[f32]) -> (f64, f64) {
    // (relative L2 error, cosine similarity)
    let (mut dd, mut bb, mut ab, mut aa) = (0f64, 0f64, 0f64, 0f64);
    for (x, y) in a.iter().zip(b) {
        let (x, y) = (*x as f64, *y as f64);
        dd += (x - y) * (x - y);
        bb += y * y;
        ab += x * y;
        aa += x * x;
    }
    (
        (dd / bb.max(1e-30)).sqrt(),
        ab / (aa.sqrt() * bb.sqrt()).max(1e-30),
    )
}

fn run(variant: &str) {
    if Device::count().unwrap_or(0) == 0 {
        eprintln!("skipped: no CUDA device");
        return;
    }
    let d = dir(variant);
    let man = Json::from_file(d.join("manifest.json")).unwrap();
    let c = &man["config"];
    let cfg = TrainConfig {
        n_layer: c["n_layer"].as_usize().unwrap(),
        n_embd: c["n_embd"].as_usize().unwrap(),
        n_head: c["n_head"].as_usize().unwrap(),
        n_kv: c["n_kv"].as_usize().unwrap(),
        head_dim: c["hd"].as_usize().unwrap(),
        n_ff: c["n_ff"].as_usize().unwrap(),
        vocab: c["vocab"].as_usize().unwrap(),
        seq_len: c["T"].as_usize().unwrap(),
        batch: c["B"].as_usize().unwrap(),
        qk_norm: c["qk_norm"].as_bool().unwrap(),
        rope_theta: c["theta"].as_f64().unwrap() as f32,
        eps: 1e-5,
        ce_chunk: 128,
        untied: c["untied"].as_bool().unwrap_or(false),
        relu2: c["relu2"].as_bool().unwrap_or(false),
        softcap: c["softcap"].as_f64().unwrap_or(0.0) as f32,
        lambdas: c["lambdas"].as_bool().unwrap_or(false),
        skips: c["skips"].as_bool().unwrap_or(false),
        ve_layers: c["ve_layers"]
            .as_array()
            .map(|a| a.iter().filter_map(|v| v.as_usize()).collect())
            .unwrap_or_default(),
        ngram: c["ngram"]
            .as_array()
            .map(|a| a.iter().filter_map(|v| v.as_usize()).collect())
            .unwrap_or_default(),
        ngram_bits: c["ngram_bits"].as_usize().unwrap_or(0),
        ngram_dim: c["ngram_dim"].as_usize().unwrap_or(0),
        attn_gate: c["attn_gate"].as_usize().unwrap_or(0),
        peri_norm: c["peri_norm"].as_bool().unwrap_or(false),
        emb_norm: c["emb_norm"].as_bool().unwrap_or(false),
        window: 0,
        window_layers: Vec::new(),
    };
    eprintln!("{variant}: structure {}", cfg.structure());
    let n_tokens = cfg.tokens();
    let mut weights: HashMap<String, Vec<f32>> = HashMap::new();
    for p in man["params"].as_array().unwrap() {
        let name = p["name"].as_str().unwrap().to_string();
        weights.insert(name.clone(), read_f32(d.join(format!("{name}.w.f32"))));
    }
    let tokens: Vec<u32> = std::fs::read(d.join("tokens.u32"))
        .unwrap()
        .chunks_exact(4)
        .map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    let mut tr = Trainer::new(cfg, 0).unwrap();
    if let Some(eos) = c["doc_eos"].as_usize() {
        tr.set_doc_mask(Some(eos as u32)).unwrap();
    }
    tr.set_params(&weights).unwrap();
    tr.zero_grads().unwrap();
    let scale = 1024.0f32;
    let loss = tr.forward_backward(&tokens, scale, n_tokens).unwrap();
    let want = man["loss"].as_f64().unwrap() as f32;
    eprintln!("{variant}: loss {loss:.5} (PyTorch {want:.5})");
    assert!((loss - want).abs() < 2e-3, "loss {loss} vs {want}");
    let grads = tr.grads_named(1.0 / scale).unwrap();
    let mut worst_rel = 0f64;
    let mut worst_cos = 1f64;
    for p in man["params"].as_array().unwrap() {
        let name = p["name"].as_str().unwrap();
        let want = read_f32(d.join(format!("{name}.g.f32")));
        let (rel, cos) = stats(&grads[name], &want);
        eprintln!("  grad {name:16}: relative error {rel:.3e}, cosine {cos:.6}");
        worst_rel = worst_rel.max(rel);
        worst_cos = worst_cos.min(cos);
    }
    assert!(worst_cos > 0.998, "worst cosine {worst_cos}");
    assert!(worst_rel < 0.08, "worst relative error {worst_rel}");

    // five AdamW steps on the same batch
    tr.set_params(&weights).unwrap();
    let mut losses = Vec::new();
    for _ in 0..5 {
        tr.zero_grads().unwrap();
        losses.push(tr.forward_backward(&tokens, scale, n_tokens).unwrap());
        let s = tr.step(1e-2, 0.9, 0.95, 1e-8, 0.1, 0.0, scale).unwrap();
        assert!(!s.found_inf);
    }
    let want_losses: Vec<f64> = man["adamw_losses_before_each_step"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_f64().unwrap())
        .collect();
    eprintln!("  AdamW losses {losses:?} (PyTorch {want_losses:?})");
    for (a, b) in losses.iter().zip(&want_losses) {
        assert!(((*a as f64) - b).abs() < 0.05 * b.max(1.0), "{a} vs {b}");
    }
    let params = tr.params_named().unwrap();
    for p in man["params"].as_array().unwrap() {
        let name = p["name"].as_str().unwrap();
        let want = read_f32(d.join(format!("{name}.w5.f32")));
        let (rel, cos) = stats(&params[name], &want);
        eprintln!("  weights after 5 steps {name:16}: relative error {rel:.3e}, cosine {cos:.6}");
        assert!(cos > 0.99, "{name}: cosine {cos}");
    }
}

#[test]
fn tiny_model_matches_pytorch() {
    run("plain");
}

